"use client"

import * as React from "react"

import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Progress } from "@/components/ui/progress"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import {
  formatCompact,
  shortAddress,
  type Orchestrator,
  type OrchestratorPage,
} from "@/lib/livepeer"

type OrchestratorTableProps = {
  orchestrators: Orchestrator[]
  initialCursor: string | null
}

function LiteralAddress({ value }: { value: string }) {
  if (!value.startsWith("0x")) return value

  return (
    <>
      <span>{value[0]}</span>
      <span>{value.slice(1)}</span>
    </>
  )
}

export function OrchestratorTable({
  orchestrators,
  initialCursor,
}: OrchestratorTableProps) {
  const [rows, setRows] = React.useState(orchestrators)
  const [nextCursor, setNextCursor] = React.useState(initialCursor)
  const [loading, setLoading] = React.useState(false)
  const [error, setError] = React.useState(false)
  const sentinelRef = React.useRef<HTMLDivElement>(null)
  const cursorInFlight = React.useRef<string | null>(null)

  const loadMore = React.useCallback(async () => {
    if (!nextCursor || loading || cursorInFlight.current === nextCursor) return

    cursorInFlight.current = nextCursor
    setLoading(true)
    setError(false)

    try {
      const response = await fetch(
        `/api/orchestrators?cursor=${encodeURIComponent(nextCursor)}`
      )
      if (!response.ok) throw new Error("Unable to load orchestrators.")

      const page: OrchestratorPage = await response.json()
      setRows((current) => {
        const knownAddresses = new Set(current.map((item) => item.address))
        return [
          ...current,
          ...page.orchestrators.filter(
            (item) => !knownAddresses.has(item.address)
          ),
        ]
      })
      setNextCursor(page.nextCursor)
    } catch {
      setError(true)
    } finally {
      cursorInFlight.current = null
      setLoading(false)
    }
  }, [loading, nextCursor])

  React.useEffect(() => {
    const sentinel = sentinelRef.current
    if (!sentinel || !nextCursor || error) return

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) void loadMore()
      },
      { rootMargin: "400px 0px" }
    )

    observer.observe(sentinel)
    return () => observer.disconnect()
  }, [error, loadMore, nextCursor])

  if (rows.length === 0) {
    return (
      <p className="rounded-md border border-dashed px-4 py-8 text-center text-sm text-muted-foreground">
        Network data is unavailable right now.
      </p>
    )
  }

  return (
    <>
      <Table>
        <TableHeader>
          <TableRow>
            <TableHead className="text-muted-foreground">
              Orchestrator
            </TableHead>
            <TableHead className="text-muted-foreground">Address</TableHead>
            <TableHead className="text-right text-muted-foreground">
              Total stake
            </TableHead>
            <TableHead className="text-right text-muted-foreground">
              Fee cut
            </TableHead>
            <TableHead className="text-muted-foreground">Status</TableHead>
            <TableHead className="w-44 text-muted-foreground">
              Avg. success rate
            </TableHead>
          </TableRow>
        </TableHeader>
        <TableBody>
          {rows.map((orchestrator) => (
            <TableRow key={orchestrator.address}>
              <TableCell className="font-identifier max-w-44 truncate font-medium">
                <LiteralAddress value={orchestrator.name} />
              </TableCell>
              <TableCell className="font-identifier font-mono text-xs text-muted-foreground">
                <LiteralAddress value={shortAddress(orchestrator.address)} />
              </TableCell>
              <TableCell className="text-right text-xs tabular-nums">
                {formatCompact(orchestrator.stakeLpt)} LPT
              </TableCell>
              <TableCell className="text-right text-xs tabular-nums">
                {orchestrator.feeCutPercent}%
              </TableCell>
              <TableCell>
                <Badge variant={orchestrator.active ? "secondary" : "outline"}>
                  {orchestrator.active ? "Active" : "Inactive"}
                </Badge>
              </TableCell>
              <TableCell>
                {orchestrator.successRate === null ? (
                  <span className="text-xs text-muted-foreground">—</span>
                ) : (
                  <div className="flex items-center gap-3">
                    <Progress
                      value={orchestrator.successRate * 100}
                      className="flex-1"
                    />
                    <span className="w-10 text-right text-xs text-muted-foreground tabular-nums">
                      {Math.round(orchestrator.successRate * 100)}%
                    </span>
                  </div>
                )}
              </TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>
      <div
        ref={sentinelRef}
        className="flex min-h-12 items-center justify-between gap-4 pt-2"
      >
        <p className="text-xs text-muted-foreground" aria-live="polite">
          {loading
            ? `Loading after ${rows.length} orchestrators…`
            : nextCursor
              ? `${rows.length} orchestrators loaded`
              : `End of registry · ${rows.length} orchestrators`}
        </p>
        {error && (
          <Button variant="outline" size="sm" onClick={() => void loadMore()}>
            Try again
          </Button>
        )}
      </div>
    </>
  )
}

const REGISTRY_URL = "https://livepeer-network-api.cloudspe.com/api/v1"
const LEADERBOARD_URL =
  "https://leaderboard-serverless.vercel.app/api/aggregated_stats"

export type NetworkStats = {
  payoutsUsd24h: number
  rewardsUsd24h: number
}

export type Orchestrator = {
  address: string
  name: string
  serviceHost: string
  stakeLpt: number
  feeCutPercent: number
  active: boolean
  successRate: number | null
}

export type OrchestratorPage = {
  orchestrators: Orchestrator[]
  nextCursor: string | null
}

type RawOrchestrator = {
  address: string
  display_name?: string
  service_uri?: string
  total_stake?: string
  fee_cut_percent?: string
  is_active?: boolean
}

type RegionStats = Record<
  string,
  { success_rate: number; round_trip_score: number; score: number }
>

export async function getNetworkStats(): Promise<NetworkStats | null> {
  try {
    const res = await fetch(`${REGISTRY_URL}/network/stats`, {
      next: { revalidate: 600 },
    })
    if (!res.ok) return null
    const raw = await res.json()
    return {
      payoutsUsd24h: Number(raw.payouts_usd_24h ?? 0),
      rewardsUsd24h: Number(raw.rewards_usd_24h ?? 0),
    }
  } catch {
    return null
  }
}

export async function getOrchestratorsPage({
  cursor,
  limit = 50,
}: {
  cursor?: string
  limit?: number
} = {}): Promise<OrchestratorPage | null> {
  try {
    const params = new URLSearchParams({ limit: String(limit) })
    if (cursor) params.set("cursor", cursor)

    const [orchRes, statsRes] = await Promise.all([
      fetch(`${REGISTRY_URL}/orchestrators?${params}`, {
        next: { revalidate: 600 },
      }),
      fetch(LEADERBOARD_URL, { next: { revalidate: 600 } }),
    ])
    if (!orchRes.ok) return null
    const raw: {
      data: RawOrchestrator[]
      meta?: { next_cursor?: string | null }
    } = await orchRes.json()
    const stats: Record<string, RegionStats> = statsRes.ok
      ? await statsRes.json()
      : {}

    return {
      orchestrators: (raw.data ?? []).map((orch) => {
        const regions = Object.values(stats[orch.address.toLowerCase()] ?? {})
        const successRate =
          regions.length > 0
            ? regions.reduce((sum, region) => sum + region.success_rate, 0) /
              regions.length
            : null
        return {
          address: orch.address,
          name: orch.display_name || shortAddress(orch.address),
          serviceHost: hostFromUri(orch.service_uri),
          stakeLpt: Number(orch.total_stake ?? 0),
          feeCutPercent: Number(orch.fee_cut_percent ?? 0),
          active: Boolean(orch.is_active),
          successRate,
        }
      }),
      nextCursor: raw.meta?.next_cursor ?? null,
    }
  } catch {
    return null
  }
}

const DOCKER_HUB_URL = "https://hub.docker.com/v2/repositories/livepeer"

export type ContainerImage = {
  tag: string
  sizeGb: number
  updatedAt: string
}

export type ContainerHubInfo = {
  pullCount: number
  updatedAt: string
  images: ContainerImage[]
}

export async function getContainerHubInfo(
  slug: string,
  tags: string[]
): Promise<ContainerHubInfo | null> {
  try {
    const [repoRes, ...tagResults] = await Promise.all([
      fetch(`${DOCKER_HUB_URL}/${slug}/`, { next: { revalidate: 3600 } }),
      ...tags.map((tag) =>
        fetch(`${DOCKER_HUB_URL}/${slug}/tags/${tag}`, {
          next: { revalidate: 3600 },
        })
      ),
    ])
    if (!repoRes.ok) return null
    const repo = await repoRes.json()
    const images: ContainerImage[] = []
    for (const res of tagResults) {
      if (!res.ok) continue
      const tag = await res.json()
      images.push({
        tag: tag.name,
        sizeGb: tag.full_size / 1e9,
        updatedAt: tag.last_updated,
      })
    }
    return {
      pullCount: Number(repo.pull_count ?? 0),
      updatedAt: String(repo.last_updated ?? ""),
      images,
    }
  } catch {
    return null
  }
}

export type GithubRepoInfo = {
  stars: number
  license: string | null
  contributors: string[]
}

export async function getGithubRepoInfo(
  repo: string
): Promise<GithubRepoInfo | null> {
  try {
    const [repoRes, contributorsRes] = await Promise.all([
      fetch(`https://api.github.com/repos/${repo}`, {
        next: { revalidate: 3600 },
      }),
      fetch(`https://api.github.com/repos/${repo}/contributors?per_page=5`, {
        next: { revalidate: 3600 },
      }),
    ])
    if (!repoRes.ok) return null
    const raw = await repoRes.json()
    const contributors: { login: string }[] = contributorsRes.ok
      ? await contributorsRes.json()
      : []
    return {
      stars: Number(raw.stargazers_count ?? 0),
      license: raw.license?.spdx_id ?? null,
      contributors: contributors.map((c) => c.login),
    }
  } catch {
    return null
  }
}

function hostFromUri(uri: string | undefined) {
  if (!uri) return ""
  try {
    return new URL(uri).hostname
  } catch {
    return uri
  }
}

export function formatCompact(value: number) {
  return Intl.NumberFormat("en-US", {
    notation: "compact",
    maximumFractionDigits: 1,
  }).format(value)
}

export function shortAddress(address: string) {
  return `${address.slice(0, 6)}…${address.slice(-4)}`
}
